pool=[]
for path in files:
    try:
        with open(path,'r',encoding='utf-8',errors='ignore') as f:
            txt=f.read()
        blocks=extract_prompt_blocks(txt)
        for b in blocks:
            pool.append((os.path.basename(path), b))
    except Exception as e:
        pass

len(pool)

